const safeName=s=>String(s||'Documento-GAMA').replace(/[^a-zA-Z0-9_-]/g,'-').slice(0,100);
function base64Blob(data,mime){if(!['application/pdf','application/xml'].includes(mime)||!data||data.length>7000000||!/^[A-Za-z0-9+/=\r\n]+$/.test(data))throw Error('DOCUMENT_UNAVAILABLE');return new Blob([Uint8Array.from(atob(data),c=>c.charCodeAt(0))],{type:mime})}
function download(blob,name){if(!boot)return;const url=URL.createObjectURL(blob);urls.add(url);const a=document.createElement('a');a.href=url;a.download=name;a.rel='noopener';document.body.append(a);a.click();a.remove();setTimeout(()=>{URL.revokeObjectURL(url);urls.delete(url)},30000)}
async function sriDownload(id,kind){const token=authEpoch,c=await client(),s=await c.auth.getSession();const r=await fetch(cfg.url+'/functions/v1/gama-sri',{method:'POST',headers:{Authorization:'Bearer '+s.data.session.access_token,apikey:cfg.publishable_key,'Content-Type':'application/json'},body:JSON.stringify({action:'download',document_type:'01',id,kind}),signal:AbortSignal.timeout(20000)}),data=await r.json();if(!r.ok)throw Error(data.error||'NOT_FOUND');if(!data.url?.startsWith(cfg.url+'/storage/v1/object/sign/sri-documents/'))throw Error('DOCUMENT_UNAVAILABLE');const file=await fetch(data.url,{signal:AbortSignal.timeout(20000)});if(!file.ok)throw Error('DOCUMENT_UNAVAILABLE');const blob=await file.blob();if(token===authEpoch)download(blob,data.filename||'Factura-SRI'+(kind==='xml'?'.xml':'.pdf'))}
async function pdfReady(){await loadScript('assets/vendor/jspdf-4.2.1.umd.min.js','sha384-qovJwSBbRDPP5cEjCp8S0UP66wrvnjaa60XMOGzTNanrThcrGfXfnZkvgY8N1KT3');await loadScript(cfg.pdf_template||'gama-pdf-template.js')}
async function statementPdf(data){const p=window.GamaPdfTemplate.layout({title:'Estado de cuenta',reference:data.customer.identification,date:data.today,company:{...data.company,configured:true}}),d=p.doc;p.text(data.customer.name,12,true);p.text('Saldo pendiente: '+money(data.total)+' · Importe vencido: '+money(data.overdue),10,true);const xs=[16,92,124,156],width=[72,30,30,38];const head=()=>{d.setFont('helvetica','bold');d.setFontSize(9);['Factura','Fecha','Vencimiento','Saldo'].forEach((v,i)=>d.text(v,xs[i],p.y));p.y+=7};head();for(const r of data.rows){const wrapped=[r.number,r.issue_date,r.due_date||'Sin vencimiento',money(r.balance)].map((v,i)=>d.splitTextToSize(String(v),width[i])),h=Math.max(...wrapped.map(x=>x.length))*4+4;if(p.y+h>269){p.next();head()}d.setFont('helvetica','normal');d.setFontSize(9);wrapped.forEach((v,i)=>d.text(v,xs[i],p.y));p.y+=h}p.finish('Los saldos incluyen pagos, notas de crédito, retenciones y ajustes registrados.');return d.output('blob')}
async function proofPdf(r){const p=window.GamaPdfTemplate.layout({title:'Prueba de entrega',reference:r.reference,date:r.date,detail:'Portal de empresas · GAMA'}),d=p.doc;p.text(r.customer,12,true);p.text(r.address);p.text('Captura: '+(r.captured_at||r.delivered_at||'No registrada'));p.text(r.latitude!=null&&r.longitude!=null?'GPS: '+r.latitude+', '+r.longitude+' · precisión '+(r.accuracy??'—')+' m':'GPS no registrado');for(const [label,data] of [['Foto de la entrega',r.photo],['Firma del receptor',r.signature]]){if(!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(data||''))continue;const props=d.getImageProperties(data),scale=Math.min(160/props.width,(label==='Firma del receptor'?45:135)/props.height),w=props.width*scale,h=props.height*scale;p.room(h+18);p.text(label,10,true);d.addImage(data,25,p.y,w,h,undefined,'FAST');p.y+=h+8}p.finish('Prueba registrada por GAMA. La fecha y el GPS se muestran cuando fueron capturados.');return d.output('blob')}
async function quotePdf(r){const p=window.GamaPdfTemplate.layout({title:'Presupuesto',reference:r.reference,date:r.date,company:{...r.company,configured:true}}),d=p.doc;p.text(r.customer.name,12,true);p.text(r.customer.identification||'');p.text(r.address||'');p.text('Validez: '+(r.valid_until||'Según condiciones acordadas'));for(const l of r.lines){p.room(22);p.text(l.description,10,true);p.text(quantity(l.quantity)+' × '+money(l.unit_price)+' · IVA '+quantity(l.tax_rate)+' % · '+money(l.line_total),9)}p.room(30);p.text('Subtotal: '+money(r.subtotal));p.text('IVA: '+money(r.tax));p.text('Total: '+money(r.total),12,true);p.finish('Documento comercial emitido por GAMA.');return d.output('blob')}
